import { t,getLocale,setLocale,LOCALE_METADATA,SUPPORTED_LOCALES,ENABLED_LOCALES } from './index.js';
const escAttr=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
export function languageSelectorHtml({id='kombax-language-selector',compact=false}={}){const current=getLocale();return `<label class="kx-language-selector ${compact?'is-compact':''}" for="${escAttr(id)}"><span>${compact?'🌐':escAttr(t('common.language.label'))}</span><select id="${escAttr(id)}" data-kombax-language-selector aria-label="${escAttr(t('common.language.selector'))}">${SUPPORTED_LOCALES.map(code=>{const m=LOCALE_METADATA[code];const enabled=ENABLED_LOCALES.includes(code);return `<option value="${code}" ${code===current?'selected':''} ${enabled?'':'disabled'}>${escAttr(m.nativeName)}${enabled?'':` · ${escAttr(t('common.language.comingSoon'))}`}</option>`}).join('')}</select></label>`;}
export function bindLanguageSelectors(root=document,{persistAccount=null,onChange=null}={}){root.querySelectorAll?.('[data-kombax-language-selector]').forEach(el=>{if(el.dataset.kombaxI18nBound==='1')return;el.dataset.kombaxI18nBound='1';el.addEventListener('change',async()=>{const locale=setLocale(el.value);if(typeof persistAccount==='function')try{await persistAccount(locale)}catch(error){console.warn('No se pudo persistir el idioma de cuenta; se conserva localmente.',error)}if(typeof onChange==='function')try{await onChange(locale,el)}catch(error){console.warn('No se pudo refrescar la interfaz tras cambiar el idioma.',error)}});});}
